# 1. List the number of films per category.
USE sakila;

SELECT c.name, COUNT(fc.film_id) AS number_of_films
FROM film_category fc
INNER JOIN category c ON c.category_id = fc.category_id
group by c.name 
order by number_of_films DESC;

# 2. Retrieve the store ID, city, and country for each store.
SELECT s.store_id, c.city, co.country #columns you want in your final table
FROM store AS s 
	JOIN address AS a ON s.address_id = a.address_id
INNER JOIN city AS c 
	ON a.city_id = c.city_id
JOIN country AS co 
	on c.country_id = co.country_id;

# 3. Calculate the total revenue generated by each store in dollars.
SELECT 
	s.store_id, 
	SUM(p.amount) AS total_revenue
FROM 
	payment AS p 
JOIN 
    customer AS c ON p.customer_id = c.customer_id
JOIN  
	store AS s ON c.store_id = s.store_id
GROUP BY 
	s.store_id;
    
# Determine the average running time of films for each category.
SELECT
	cat.name AS category_name,
	AVG(f.length) AS avg_running_time
FROM 
	film_category AS fc
JOIN 
	film AS f on fc.film_id = f.film_id
JOIN 
	category AS cat ON fc.category_id = cat.category_id
GROUP BY
	cat.name;